import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.*;
import static org.apache.commons.csv.Constants.COMMENT;
import static org.apache.commons.csv.Constants.CR;
import static org.apache.commons.csv.Constants.LF;
import static org.apache.commons.csv.Constants.SP;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.sql.ResultSet;
import java.sql.SQLException;

public class CSVPrinterTest{
private CSVPrinter printer;
    private MockAppendable out;
    private CSVFormat format;

    @Before
    public void setUp() throws IOException{
        out = new MockAppendable();
        format = CSVFormat.DEFAULT;
        printer = new CSVPrinter(out, format);
    }

    @After
    public void tearDown()throws Exception{
        printer.close();
    }

    @Test
    public void testPrint() throws Exception{
        // given
        Object value = "test";
        String expected = "test";
        // when
        printer.print(value);
        // then
        assertThat(out.toString(), equalTo(expected));
    }

    @Test
    public void testPrintNull() throws Exception{
        // given
        Object value = null;
        String expected = format.getNullString() == null ? "" : format.getNullString();
        // when
        printer.print(value);
        // then
        assertThat(out.toString(), equalTo(expected));
    }

    @Test
    public void testPrintCustomNullString() throws Exception{
        // given
        Object value = null;
        String customNullString = "N/A";
        format = CSVFormat.DEFAULT.withNullString(customNullString);
        printer = new CSVPrinter(out, format);
        String expected = customNullString;
        // when
        printer.print(value);
        // then
        assertThat(out.toString(), equalTo(expected));
    }

    @Test(expected = IOException.class)
    public void testIOException() throws Exception{
        // given
        Object value = "test";
        MockAppendable failingOut = new FailingAppendable();
        printer = new CSVPrinter(failingOut, format);
        // when
        printer.print(value);
    }

    @Test
    public void testClose() throws Exception{
        // given
        // when
        printer.close();
        // then
        assertTrue(out.isClosed());
    }

    @Test
    public void testFlush() throws Exception{
        // given
        // when
        printer.flush();
        // then
        assertTrue(out.isFlushed());
    }

    private static class MockAppendable implements Appendable, Closeable, Flushable{
        private StringBuilder sb = new StringBuilder();
        private boolean closed = false;
        private boolean flushed = false;

        @Override
        public Appendable append(char c) throws IOException{
            if (closed) throw new IOException("closed");
            sb.append(c);
            return this;
        }

        @Override
        public Appendable append(CharSequence csq)throws IOException{
            if (closed) throw new IOException("closed");
            sb.append(csq);
            return this;
        }

        @Override
        public Appendable append(CharSequence csq, int start, int end)throws IOException{
            if (closed) throw new IOException("closed");
            sb.append(csq, start, end);
            return this;
        }

        @Override
        public void close()throws IOException{
            closed = true;
        }

        @Override
        public void flush()throws IOException{
            flushed = true;
        }

        @Override
        public String toString(){
            return sb.toString();
        }

        public boolean isClosed(){
            return closed;
        }

        public boolean isFlushed(){
            return flushed;
        }
    }

    private static class FailingAppendable extends MockAppendable{
        @Override
        public Appendable append(char c) throws IOException{
            throw new IOException();
        }
    }
}
