import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.NoSuchElementException;
import java.util.TreeMap;

public class CSVParserTest{
private CSVParser csvParser;
    private Reader reader;
    private static final CSVFormat DEFAULT_CSV_FORMAT = CSVFormat.DEFAULT;

    @Before
    public void setUp() throws Exception{
        String testCSV = "a,b,c\n" +
                         "1,2,3\n" +
                         "4,5,6";
        reader = new StringReader(testCSV);
        csvParser = new CSVParser(reader, DEFAULT_CSV_FORMAT);
    }

    @After
    public void tearDown() throws Exception{
        csvParser.close();
    }

    @Test
    public void testIterator() throws Exception {
        Iterator<CSVRecord> iterator = csvParser.iterator();
        Assert.assertNotNull(iterator);
        int count = 0;
        while (iterator.hasNext()) {
            CSVRecord record = iterator.next();
            count++;
            Assert.assertNotNull(record);
        }
        Assert.assertEquals(3, count); // 3 records: header and 2 data records
    }

    @Test
    public void testGetRecords() throws Exception {
        List<CSVRecord> records = csvParser.getRecords();
        Assert.assertNotNull(records);
        Assert.assertEquals(3, records.size()); // 3 records: header and 2 data records
    }

    @Test
    public void testNextRecord() throws Exception {
        CSVRecord record = csvParser.nextRecord();
        Assert.assertNotNull(record);
        Assert.assertEquals("a", record.get(0));
        Assert.assertEquals("b", record.get(1));
        Assert.assertEquals("c", record.get(2));

        record = csvParser.nextRecord();
        Assert.assertNotNull(record);
        Assert.assertEquals("1", record.get(0));
        Assert.assertEquals("2", record.get(1));
        Assert.assertEquals("3", record.get(2));

        record = csvParser.nextRecord();
        Assert.assertNotNull(record);
        Assert.assertEquals("4", record.get(0));
        Assert.assertEquals("5", record.get(1));
        Assert.assertEquals("6", record.get(2));

        Assert.assertNull(csvParser.nextRecord());
    }

    @Test(expected = NoSuchElementException.class)
    public void testNextRecordExhausted() throws Exception {
        while (csvParser.nextRecord() != null) {}

        csvParser.nextRecord();
    }

    @Test
    public void testGetCurrentLineNumber() throws Exception {
        Assert.assertEquals(0, csvParser.getCurrentLineNumber());

        csvParser.nextRecord();
        Assert.assertEquals(1, csvParser.getCurrentLineNumber());

        csvParser.nextRecord();
        Assert.assertEquals(2, csvParser.getCurrentLineNumber());
    }

    @Test
    public void testGetRecordNumber() throws Exception {
        Assert.assertEquals(0, csvParser.getRecordNumber());

        csvParser.nextRecord();
        Assert.assertEquals(1, csvParser.getRecordNumber());

        csvParser.nextRecord();
        Assert.assertEquals(2, csvParser.getRecordNumber());
    }

    @Test
    public void testGetHeaderMap() throws Exception {
        Map<String, Integer> headerMap = csvParser.getHeaderMap();
        Assert.assertNotNull(headerMap);
        Assert.assertEquals(3, headerMap.size());
        Assert.assertEquals(0, (int) headerMap.get("a"));
        Assert.assertEquals(1, (int) headerMap.get("b"));
        Assert.assertEquals(2, (int) headerMap.get("c"));
    }

    @Test
    public void testIsClosed() throws Exception {
        Assert.assertFalse(csvParser.isClosed());

        csvParser.close();
        Assert.assertTrue(csvParser.isClosed());
    }

    @Test
    public void testClose() throws Exception {
        csvParser.close();
        Assert.assertTrue(csvParser.isClosed());
    }
}
